<?php
function guided_count_is($b){return !empty(final_count_meta($b)['guided_version']);}
function guided_count_editable($b,$revision){final_count_owner($b);if(!guided_count_is($b)||!in_array($b['status'],['Exported','Error','Validated'],true))throw new Exception('Submitted counts are locked. Request a return for correction first.');if((int)$b['revision']!==(int)$revision)throw new Exception('This adjustment changed. Reopen the latest record before editing.');}
function guided_count_products($rows,$scope){$ids=[];$header=null;$item=null;$qty=[];foreach($rows as $n=>$row){$keys=array_map(fn($v)=>norm((string)$v),$row);foreach(['master sku','item code','item','product / sku','product'] as $h){$i=array_search($h,$keys,true);if($i!==false){$item=$i;break;}}if($item===null)continue;$qty=[];foreach(array_slice(final_count_headers($scope),1) as $h){$i=array_search(norm($h),$keys,true);if($i===false){$qty=[];break;}$qty[]=$i;}if($qty){$header=$n;break;}$item=null;}if($header===null)throw new Exception('Required columns: '.implode(', ',final_count_headers($scope)).'.');foreach(array_slice($rows,$header+1) as $row){$has=false;foreach($qty as $i)if(trim((string)($row[$i]??''))!=='')$has=true;if(!$has)continue;$pid=return_match(trim((string)($row[$item]??'')));if($pid)$ids[(int)$pid]=(int)$pid;}if(!$ids)throw new Exception('No recognized counted products. Check the Master SKU and quantity columns.');return array_values($ids);}
function guided_count_extend($b,$ids){$known=array_map('intval',array_column(count_lines($b['id']),'product_id'));foreach(array_diff($ids,$known) as $pid){$p=active_product($pid);$q=db()->prepare("SELECT b.batch_ref FROM inventory_count_batches b JOIN inventory_count_lines l ON l.batch_id=b.id WHERE l.product_id=? AND b.id<>? AND b.status NOT IN ('Applied','Cancelled','Reversed') LIMIT 1");$q->execute([$pid,$b['id']]);if($other=$q->fetchColumn())throw new Exception('Another open count includes this product: '.$other);$q=db()->prepare('SELECT updated_at FROM beginning_balances WHERE product_id=?');$q->execute([$pid]);if(($begin=$q->fetchColumn())&&$begin>$b['cutoff_at'])throw new Exception('The inventory date predates this product beginning balance.');$q=db()->prepare("SELECT b.id,b.status FROM inventory_count_batches b JOIN inventory_count_lines l ON l.batch_id=b.id WHERE l.product_id=? AND b.id<>? AND b.cutoff_at=? AND b.status IN ('Applied','Cancelled','Reversed')");$q->execute([$pid,$b['id'],$b['cutoff_at']]);foreach($q as $earlier){if($earlier['status']==='Applied')throw new Exception('This product and count cutoff were already posted. Use a linked reversal.');if(!final_count_related((int)(final_count_meta($b)['supersedes']??0),$earlier['id']))throw new Exception('Use the linked corrected adjustment for this product and count cutoff.');}$c=final_count_conditions_at($pid,$b);if(min($c['packaging'],$c['damaged'],$c['other'])<0)throw new Exception('Reconcile restricted stock before counting this product.');db()->prepare('INSERT INTO inventory_count_lines(batch_id,product_id,master_sku,product_name,on_hand,sellable_on_hand,nonsellable_on_hand,stock_signature,snapshot_conditions) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$b['id'],$pid,$p['master_sku'],$p['name'],array_sum($c),$c['good'],$c['packaging']+$c['damaged']+$c['other'],final_count_signature($pid,$b),json_encode($c)]);}}
function guided_count_input($input){$data=['count_date'=>process_date($input['count_date']??''),'count_scope'=>$input['count_scope']??'Sellable','entry_method'=>$input['entry_method']??'Upload','reason'=>process_reason($input['reason']??''),'support_reference'=>workflow_text($input['support_reference']??'','Supporting Reference',255),'cutoff_ack'=>!empty($input['cutoff_ack']),'items'=>$input['items']??[]];if(!in_array($data['count_scope'],['Sellable','All Conditions'],true)||!in_array($data['entry_method'],['Upload','Manual'],true))throw new Exception('Select a valid count scope and entry method.');if(strlen($data['support_reference'])<3)throw new Exception('Supporting reference must contain at least 3 characters.');if(!$data['cutoff_ack'])throw new Exception('Confirm the inventory date and movements during counting.');require_open_inventory_date($data['count_date']);return $data;}
function guided_count_validate($input,$rows,$filename,$fileHash=null,$stored=null){
 adjustment_access();$data=guided_count_input($input);if($data['entry_method']==='Manual'){
  if(!is_array($data['items'])||count($data['items'])<1||count($data['items'])>500)throw new Exception('Enter 1 to 500 product lines.');$rows=[final_count_headers($data['count_scope'])];$seen=[];
  foreach($data['items'] as $item){$p=active_product(whole_number($item['product_id']??'','Product',1));if(isset($seen[$p['id']]))throw new Exception('Combine duplicate products into one line.');$seen[$p['id']]=true;$row=[$p['master_sku']];foreach($data['count_scope']==='Sellable'?['good']:['good','packaging','damaged','other'] as $k)$row[]=trim((string)($item[$k]??''));$rows[]=$row;}$filename='Manual Inventory Count';$fileHash=hash('sha256',json_encode($rows));
 }
 $ids=guided_count_products($rows,$data['count_scope']);
 return process_transaction(function()use($input,$data,$rows,$filename,$fileHash,$stored,$ids){$id=(int)($input['batch_id']??0);
  if($id){$b=final_count_open($id,true);guided_count_editable($b,$input['revision']??-1);$oldMeta=final_count_meta($b);if($data['count_date']!==$b['count_date']||$data['count_scope']!==$oldMeta['count_scope'])throw new Exception('Keep the original inventory date and scope. Cancel this record to start a different count.');adjustment_event($id,'Count corrected before submission',['revision'=>$b['revision'],'previous_reason'=>$b['reason'],'previous_support_reference'=>$b['support_reference'],'previous_counts'=>array_map(fn($l)=>['sku'=>$l['master_sku'],'conditions'=>json_decode($l['final_conditions']??'null',true)],array_filter(count_lines($id),fn($l)=>$l['actual_count']!==null))]);}
  else{$id=final_count_create(['count_date'=>$data['count_date'],'count_scope'=>$data['count_scope'],'cutoff_ack'=>1,'entry_method'=>$data['entry_method'],'product_ids'=>$ids,'supersedes'=>(int)($input['supersedes']??0)]);$b=count_batch($id);}
  guided_count_extend($b,$ids);
  $m=final_count_meta($b);$m['guided_version']='5.6.0';$m['entry_method']=$data['entry_method'];$m['guided_input']=$data;$m['last_evidence_path']=$stored;$m['last_evidence_name']=$filename;
  db()->prepare("UPDATE inventory_count_batches SET status='Exported',filter_json=? WHERE id=?")->execute([json_encode($m),$id]);db()->prepare('UPDATE inventory_count_lines SET actual_count=NULL,variance=NULL,actual_good=NULL,actual_damaged=NULL,final_conditions=NULL,remarks=NULL WHERE batch_id=?')->execute([$id]);
  $errors=final_count_upload($id,$rows,$filename,$fileHash,$stored,['reason'=>$data['reason'],'support_reference'=>$data['support_reference'],'guided_revision'=>$b['revision']]);return ['id'=>$id,'errors'=>$errors];
 });
}
function guided_count_return($id,$revision,$reason){adjustment_access();$reason=process_reason($reason);return process_transaction(function()use($id,$revision,$reason){$b=final_count_open($id,true);if(!guided_count_is($b)||!in_array($b['status'],['Submitted','Awaiting Approval'],true)||(int)$b['revision']!==(int)$revision)throw new Exception('Only the current pending request can be returned.');$m=final_count_meta($b);unset($m['validation_digest'],$m['submitted_digest'],$m['submitted_at'],$m['submitted_by']);$m['correction_reason']=$reason;db()->prepare("UPDATE inventory_count_batches SET status='Error',revision=revision+1,reviewed_by=NULL,reviewed_name=NULL,reviewed_role=NULL,reviewed_at=NULL,review_digest=NULL,error_json=?,filter_json=? WHERE id=?")->execute([json_encode(['Returned for correction: '.$reason]),json_encode($m),$id]);adjustment_event($id,'Returned for correction',['reason'=>$reason,'previous_status'=>$b['status'],'previous_reviewer'=>$b['reviewed_name'],'original_evidence_preserved'=>true]);audit('Return adjustment for correction','Inventory Count',$b['batch_ref'],$reason);});}
function guided_count_quantity($pid,$date,$scope,$id=0){adjustment_access();active_product($pid);if($id){$b=count_batch($id);if(!guided_count_is($b))throw new Exception('Select a guided adjustment.');$q=db()->prepare('SELECT snapshot_conditions FROM inventory_count_lines WHERE batch_id=? AND product_id=?');$q->execute([$id,$pid]);$json=$q->fetchColumn();$c=$json?json_decode($json,true):final_count_conditions_at($pid,$b);$scope=final_count_meta($b)['count_scope'];}else{$date=process_date($date);require_open_inventory_date($date);$b=['count_date'=>$date,'cutoff_at'=>$date<date('Y-m-d')?$date.' 23:59:59':date('Y-m-d H:i:s'),'filter_json'=>json_encode(['historical'=>$date<date('Y-m-d')])];$c=final_count_conditions_at($pid,$b);}return ['quantity'=>$scope==='Sellable'?$c['good']:array_sum($c),'conditions'=>$c];}
function guided_count_refresh($id,$revision){return process_transaction(function()use($id,$revision){$b=final_count_open($id,true);guided_count_editable($b,$revision);if($b['status']!=='Validated')throw new Exception('Validate the counts before refreshing.');final_count_check($id);$m=final_count_meta($b);$previous=$m['validation_digest']??'';db()->prepare('UPDATE inventory_count_batches SET revision=revision+1 WHERE id=?')->execute([$id]);$a=final_count_plan($id);$m['validation_digest']=$a['digest'];db()->prepare('UPDATE inventory_count_batches SET filter_json=? WHERE id=?')->execute([json_encode($m),$id]);adjustment_event($id,'Projection refreshed',['previous_digest'=>$previous,'digest'=>$a['digest'],'physical_recount_required'=>false]);});}
